class LmdbRuntimeFilterRelocatorTest {

	@Test
	void movesASelectiveFilterBeforeTheLargeExpansionButUsesHysteresis() {
		LmdbRuntimeFilterRelocator relocator = new LmdbRuntimeFilterRelocator();
		LmdbRuntimeFilterRelocator.Stage[] stages = {
				new LmdbRuntimeFilterRelocator.Stage(0, 1, 1000, 1, 1000),
				new LmdbRuntimeFilterRelocator.Stage(1, 3, 1000, 20, 50),
				new LmdbRuntimeFilterRelocator.Stage(2, 7, 20_000, 10, 1)
		};
		LmdbRuntimeFilterRelocator.Filter filter = new LmdbRuntimeFilterRelocator.Filter(44, 3, 8, 0.1, true, false);
		for (int i = 0; i < 8; i++) {
			relocator.observe(44, 10_000, 200, 80_000);
		}
		assertEquals(1, relocator.place(filter, stages, 2).stageOrdinal());
	}
}
